<?php require '../config/database.php';auth();if(($_SESSION['role']??'')!=='admin')die('ليس لديك صلاحية');$rows=$pdo->query('SELECT id,username,full_name,role,status,created_at FROM users ORDER BY id DESC')->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>المستخدمون</h1><a class="btn" href="add.php">إضافة مستخدم</a><table><tr><th>#</th><th>اسم المستخدم</th><th>الاسم</th><th>الدور</th><th>الحالة</th><th>الإجراء</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=$r['username']?></td><td><?=$r['full_name']?></td><td><?=$r['role']?></td><td><?=$r['status']?></td><td><a href="edit.php?id=<?=$r['id']?>">تعديل</a> | <a href="delete.php?id=<?=$r['id']?>">حذف</a></td></tr><?php endforeach;?></table></main>
